import { Injectable } from "@nestjs/common";
import type { CommitmentCollectionDto } from "#/modules/politics/schema/dto/commitment-collection.dto.ts";
import type { MakerCommitmentsDto } from "#/modules/politics/schema/dto/maker-commitments.dto.ts";
import { ListCommitmentsUseCase } from "#/modules/politics/features/promises/use-cases/list-commitments.repository.ts";

/**
 * The Promises contract the controller calls, then its implementation: each method
 * delegates to the use case for that operation. Regenerated by Dryv; the use cases hold the logic.
 */
export abstract class PoliticsPromisesService {
  abstract listCommitments(input: MakerCommitmentsDto): Promise<CommitmentCollectionDto>;
}

@Injectable()
export class PoliticsPromisesServiceImpl extends PoliticsPromisesService {
  constructor(private readonly listCommitmentsUseCase: ListCommitmentsUseCase) {
    super();
  }

  listCommitments(input: MakerCommitmentsDto): Promise<CommitmentCollectionDto> {
    return this.listCommitmentsUseCase.execute(input);
  }
}
